"""Read ADDA output files and write its orientation-averaging parameter file.

Formats follow the ADDA 1.4 manual and source:

* ``CrossSec-X`` / ``CrossSec-Y`` (one per incident polarization) or ``CrossSec``
  (orientation averaged, unpolarized light), manual §C.7. ADDA writes
  ``"Cext\\t= %.10g\\nQext\\t= %.10g\\n"`` and the same for Cabs, Csca, and vector
  quantities such as ``g\\t= (gx,gy,gz)`` (src/CalculateE.c). Cross sections are in
  the length unit of ``-lambda``/``-size`` squared.
* ``log`` (manual §C.4): first line ``Generated by ADDA v.<version>``, plus
  ``Total number of occupied dipoles: N``, ``box dimensions: NxxNyxNz`` and
  ``Total number of iterations: N``.
* ``avg_params.dat`` (manual §B.2): sections ``alpha:``, ``beta:``, ``gamma:``,
  each with ``min``, ``max``, ``Jmin``, ``Jmax``, ``eps``, ``equiv``, ``periodic``
  in that order.
"""

from __future__ import annotations

import re
from pathlib import Path

_LINE = re.compile(r"^\s*([A-Za-z][\w.]*)\s*=\s*(.+?)\s*$")
_VEC = re.compile(r"^\(\s*([^,]+),\s*([^,]+),\s*([^)]+)\)$")


def parse_cross_sections(text: str) -> dict[str, float | tuple[float, float, float]]:
    """Parse a CrossSec file: ``{"Cext": ..., "Qext": ..., "Cabs": ..., "g": (gx, gy, gz), ...}``."""
    out: dict[str, float | tuple[float, float, float]] = {}
    for raw in text.splitlines():
        m = _LINE.match(raw)
        if not m:
            continue
        key, val = m.group(1), m.group(2)
        vec = _VEC.match(val)
        try:
            out[key] = tuple(float(v) for v in vec.groups()) if vec else float(val)
        except ValueError:
            continue
    if "Cext" not in out:
        raise ValueError("no 'Cext' entry found in ADDA CrossSec output")
    return out


def cross_section_file(run_dir: str | Path, orientation_average: bool) -> Path:
    """The CrossSec file that holds the result for our incident polarization.

    We always map our polarization onto ADDA's Y polarization, which ADDA computes
    first and always saves (CrossSec-Y). Orientation averages go to CrossSec."""
    return Path(run_dir) / ("CrossSec" if orientation_average else "CrossSec-Y")


def read_cross_sections(run_dir: str | Path, orientation_average: bool) -> dict:
    path = cross_section_file(run_dir, orientation_average)
    if not path.is_file():
        found = sorted(p.name for p in Path(run_dir).glob("CrossSec*"))
        raise FileNotFoundError(f"ADDA did not write {path.name} in {run_dir} (found: {found or 'none'})")
    return parse_cross_sections(path.read_text(encoding="utf-8", errors="replace"))


_LOG_PATTERNS = {
    "version": (re.compile(r"Generated by ADDA v\.?\s*(\S+)"), str),
    "dipoles": (re.compile(r"Total number of occupied dipoles:\s*(\d+)"), int),
    "grid": (re.compile(r"box dimensions:\s*(\d+)x(\d+)x(\d+)"), None),
    "dipoles_per_lambda": (re.compile(r"Dipoles/lambda:\s*([-+0-9.eE]+)"), float),
    "dipole_size": (re.compile(r"Dipole size:\s*([-+0-9.eE]+)"), float),
    "iterations": (re.compile(r"Total number of iterations:\s*(\d+)"), int),
    "polarizability": (re.compile(r"Polarizability relation:\s*'([^']*)'"), str),
    "iterative_method": (re.compile(r"Iterative Method:\s*(.+)"), str),
    "symmetries": (re.compile(r"Symmetries:\s*(.+)"), str),
}


def parse_log(text: str) -> dict:
    """Pick the provenance-relevant facts out of an ADDA log file (missing ones are omitted)."""
    out: dict = {}
    for key, (pat, conv) in _LOG_PATTERNS.items():
        m = pat.search(text)
        if not m:
            continue
        out[key] = [int(g) for g in m.groups()] if conv is None else conv(m.group(1).strip())
    return out


def read_log(run_dir: str | Path) -> dict:
    path = Path(run_dir) / "log"
    return parse_log(path.read_text(encoding="utf-8", errors="replace")) if path.is_file() else {}


def parse_version(text: str) -> str | None:
    """Version from ``adda -V`` output or a log ("ADDA v.1.4.0" or "ADDA v1.4.0")."""
    m = re.search(r"ADDA\s+v\.?\s*([0-9][\w.\-]*)", text)
    return m.group(1) if m else None


def avg_params_text(beta_jmax: int = 4, gamma_jmax: int = 3, eps: float = 0.0) -> str:
    """An avg_params.dat for full orientation averaging (manual §B.2).

    alpha (rotation about the incident direction) does not change cross sections and
    ADDA ignores its range when only cross sections are averaged (``-scat_matr none``).
    beta is sampled uniformly in cos(beta) by ADDA; beta and gamma use Romberg
    integration with 2**Jmax + 1 points at most (one fewer for periodic angles)."""

    def section(name, lo, hi, jmax, equiv, periodic):
        return (f"{name}:\nmin={lo:g}\nmax={hi:g}\nJmin=2\nJmax={jmax}\neps={eps:g}\n"
                f"equiv={'true' if equiv else 'false'}\nperiodic={'true' if periodic else 'false'}\n")

    return ("# orientation averaging parameters written by lightsmith-adda (ADDA manual, section B.2)\n"
            + section("alpha", 0, 360, 4, True, True)
            + section("beta", 0, 180, beta_jmax, False, False)
            + section("gamma", 0, 360, gamma_jmax, True, True))
